package com.paymesh.backend.security.accounts;
import java.util.*;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.mock.web.MockHttpServletRequest;
import com.paymesh.backend.security.auth.AuthBrowserPolicy;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class SessionRecoverySafetyTest {
 @Test void otpDisabledByDefaultDoesNotConnectOrExposeKey(){var ds=mock(DataSource.class);var gate=new LocalDemoRecoveryGate(new MockEnvironment(),ds);assertFalse(gate.enabled());assertThrows(IllegalStateException.class,gate::key);verifyNoInteractions(ds);}
 MockEnvironment local(){var e=new MockEnvironment();e.setActiveProfiles("demo");return e.withProperty("server.address","127.0.0.1").withProperty("server.port","18080").withProperty("spring.datasource.url",AdminRecoveryDatabaseGuard.TARGET).withProperty("spring.datasource.username","paymesh_demo_user").withProperty("paymesh.sessions.origin","http://127.0.0.1:5500").withProperty("paymesh.sessions.local-http","true").withProperty("paymesh.demo.password-recovery.operator-confirmation","NO_PUBLIC_PROXY_OR_TUNNEL");}
 @Test void flagAlonePublicProfilesAndNonDemoTargetsFailClosed(){assertThrows(IllegalStateException.class,()->LocalDemoRecoveryGate.requireSafeConfiguration(new MockEnvironment()));assertDoesNotThrow(()->LocalDemoRecoveryGate.requireSafeConfiguration(local()));for(String profile:List.of("production","development","cloud")){var e=local();e.setActiveProfiles(profile);assertThrows(IllegalStateException.class,()->LocalDemoRecoveryGate.requireSafeConfiguration(e));}for(var entry:Map.of("server.address","0.0.0.0","server.port","8080","spring.datasource.url","jdbc:postgresql://127.0.0.1:5432/paymesh_db","spring.datasource.username","postgres","server.forward-headers-strategy","framework","paymesh.demo.password-recovery.operator-confirmation","missing").entrySet()){var e=local().withProperty(entry.getKey(),entry.getValue());assertThrows(IllegalStateException.class,()->LocalDemoRecoveryGate.requireSafeConfiguration(e));}}
 @Test void realTargetIsVerifiedAndWrongMetadataCannotEnableRecovery()throws Exception {var ds=mock(DataSource.class);var c=mock(java.sql.Connection.class);var metadata=mock(java.sql.DatabaseMetaData.class);when(ds.getConnection()).thenReturn(c);when(c.getMetaData()).thenReturn(metadata);when(metadata.getURL()).thenReturn("jdbc:postgresql://127.0.0.1:55441/paymesh_isolated_test");var env=local().withProperty("paymesh.demo.password-recovery.enabled","true").withProperty("paymesh.demo.password-recovery.key","k".repeat(64));assertThrows(IllegalStateException.class,()->new LocalDemoRecoveryGate(env,ds));}
 @Test void insecureSessionCookieConfigurationIsRestrictedAndHttpsIsSecure(){assertThrows(IllegalStateException.class,()->new AuthBrowserPolicy(new MockEnvironment().withProperty("paymesh.sessions.local-http","true")));assertThrows(IllegalStateException.class,()->new AuthBrowserPolicy(new MockEnvironment().withProperty("paymesh.sessions.origin","http://public.test")));var p=new AuthBrowserPolicy(new MockEnvironment().withProperty("paymesh.sessions.origin","https://paymesh.test"));assertTrue(p.cookie("x".repeat(43),true,java.time.Instant.now().plusSeconds(1000)).contains("Secure"));var request=new MockHttpServletRequest();request.addHeader("Origin","https://paymesh.test");assertFalse(p.allowed(request));request.addHeader("X-PayMesh-CSRF","1");assertTrue(p.allowed(request));request.addHeader("Origin","https://evil.test");assertFalse(p.allowed(request));}
 @Test void localCookieExceptionRequiresReviewedLoopbackDeployment(){var p=new AuthBrowserPolicy(local());assertFalse(p.cookie("x".repeat(43),false,java.time.Instant.now().plusSeconds(1000)).contains("Secure"));assertFalse(p.cookie("x".repeat(43),false,java.time.Instant.now().plusSeconds(1000)).contains("Max-Age"));}
}
